import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose2d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride_h, int stride_w,
                                       int padding_h, int padding_w,
                                       int dilation_h, int dilation_w,
                                       int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled transposed-conv2d kernel (grouped, dilated, padded, strided).
// One block computes a tile of output spatial positions for a fixed batch n,
// group g, and a small tile of output channels (CoutPerBlock) within that group.
template <typename T>
__global__ void convtranspose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Hout, int Wout,
    int kH, int kW,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups,
    int Cin_per_group, int Cout_per_group,
    int CoutPerBlock)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 8;

  const int tid = threadIdx.x;

  // Decode block coordinates
  const int nz       = blockIdx.z;          // encodes (n, g)
  const int n        = nz / groups;
  const int g        = nz % groups;

  const int oc_tile      = blockIdx.y;
  const int oc_local_base= oc_tile * CoutPerBlock;
  const int oc_base      = g * Cout_per_group + oc_local_base;

  const int cin_start = g * Cin_per_group;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides for contiguous NCHW layout
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Weight layout: (Cin_total, Cout_per_group, kH, kW), row-major contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, kH, kW),
      make_stride((int64_t)Cout_per_group * kH * kW, (int64_t)kH * kW, (int64_t)kW, Int<1>{})
  );

  // Shared memory: weight tile of shape (Cin_per_group, kH, kW, CoutPerBlock).
  // CoutPerBlock is placed as the fastest-varying dimension so that the inner
  // accumulation loop can read 4 output-channel weights at once via a single
  // 16B-aligned float4 shared-memory load instead of 4 separate scalar loads.
  extern __shared__ int4 smem_raw4[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw4);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Cin_per_group, kH, kW, CoutPerBlock),
      make_stride((int64_t)kH * kW * CoutPerBlock, (int64_t)kW * CoutPerBlock, (int64_t)CoutPerBlock, Int<1>{})
  );

  const int weight_tile_elems = CoutPerBlock * Cin_per_group * kH * kW;
  for (int idx = tid; idx < weight_tile_elems; idx += Threads) {
    int rem = idx;
    int kw = rem % kW; rem /= kW;
    int kh = rem % kH; rem /= kH;
    int cin = rem % Cin_per_group; rem /= Cin_per_group;
    int cc = rem;

    int oc_local = oc_local_base + cc;
    int ic_global = cin_start + cin;

    T wval = T(0);
    if (oc_local < Cout_per_group && ic_global < Cin) {
      wval = mW(ic_global, oc_local, kh, kw);
    }
    sW(cin, kh, kw, cc) = wval;
  }
  __syncthreads();

  // Precompute output position indices for this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Accumulators, init with bias
  float acc[16][PVec]; // CoutPerBlock assumed <= 16
  #pragma unroll
  for (int cc = 0; cc < 16; ++cc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = 0.0f;
    }
  }
  if (B != nullptr) {
    for (int cc = 0; cc < CoutPerBlock; ++cc) {
      int oc_global = oc_base + cc;
      float bval = (oc_global < Cout) ? (float)B[oc_global] : 0.0f;
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        acc[cc][i] = bval;
      }
    }
  }

  for (int kh = 0; kh < kH; ++kh) {
    int ih_i[PVec];
    bool vh_i[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int num = oh_arr[i] + padding_h - kh * dilation_h;
      bool ok = (p_idx[i] < P_total) && (num % stride_h == 0);
      int ih = ok ? (num / stride_h) : -1;
      ok = ok && (ih >= 0) && (ih < H);
      ih_i[i] = ih;
      vh_i[i] = ok;
    }
    // Precompute indices/validity for kw = 0, and prime the cin=0 x value.
    int iw_i[PVec];
    bool vw_i[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int num = ow_arr[i] + padding_w - 0 * dilation_w;
      bool ok = vh_i[i] && (num % stride_w == 0);
      int iw = ok ? (num / stride_w) : -1;
      ok = ok && (iw >= 0) && (iw < Win);
      iw_i[i] = iw;
      vw_i[i] = ok;
    }
    float xval_cur[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      xval_cur[i] = (Cin_per_group > 0 && vw_i[i]) ? (float)mX(cin_start, ih_i[i], iw_i[i]) : 0.0f;
    }
    for (int kw = 0; kw < kW; ++kw) {
      const bool has_next_kw = (kw + 1 < kW);
      int iw_next[PVec];
      bool vw_next[PVec];
      if (has_next_kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          int num = ow_arr[i] + padding_w - (kw + 1) * dilation_w;
          bool ok = vh_i[i] && (num % stride_w == 0);
          int iw = ok ? (num / stride_w) : -1;
          ok = ok && (iw >= 0) && (iw < Win);
          iw_next[i] = iw;
          vw_next[i] = ok;
        }
      }
      float xval_next_kw[PVec];
      for (int cin = 0; cin < Cin_per_group; ++cin) {
        float xval_next[PVec];
        const bool is_last_cin = (cin + 1 == Cin_per_group);
        if (!is_last_cin) {
          int ic_next = cin_start + cin + 1;
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xval_next[i] = vw_i[i] ? (float)mX(ic_next, ih_i[i], iw_i[i]) : 0.0f;
          }
        } else if (has_next_kw) {
          // Prefetch cin=0 x-value for the next kw during the last cin
          // iteration of the current kw, hiding load latency behind the
          // FMA work below.
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xval_next_kw[i] = vw_next[i] ? (float)mX(cin_start, ih_i[i], iw_next[i]) : 0.0f;
          }
        }
        const int64_t wrow_off = ((int64_t)cin * kH * kW + (int64_t)kh * kW + kw) * CoutPerBlock;
        const T* wrow = sW_ptr + wrow_off;
        int cc = 0;
        #pragma unroll
        for (; cc + 4 <= CoutPerBlock && cc + 4 <= 16; cc += 4) {
          float4 w4 = *reinterpret_cast<const float4*>(wrow + cc);
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            acc[cc + 0][i] += xval_cur[i] * w4.x;
            acc[cc + 1][i] += xval_cur[i] * w4.y;
            acc[cc + 2][i] += xval_cur[i] * w4.z;
            acc[cc + 3][i] += xval_cur[i] * w4.w;
          }
        }
        #pragma unroll
        for (; cc < 16; ++cc) {
          if (cc >= CoutPerBlock) break;
          float wval = (float)wrow[cc];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            acc[cc][i] += xval_cur[i] * wval;
          }
        }
        if (!is_last_cin) {
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xval_cur[i] = xval_next[i];
          }
        }
      }
      if (has_next_kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          iw_i[i] = iw_next[i];
          vw_i[i] = vw_next[i];
          xval_cur[i] = xval_next_kw[i];
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < 16; ++cc) {
    if (cc >= CoutPerBlock) break;
    int oc_global = oc_base + cc;
    if (oc_global >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc_global, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor convtranspose2d_forward(torch::Tensor x,
                                       torch::Tensor weight,
                                       c10::optional<torch::Tensor> bias,
                                       int stride_h, int stride_w,
                                       int padding_h, int padding_w,
                                       int dilation_h, int dilation_w,
                                       int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must be [Cin, Cout/groups, kH, kW]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H   = x_c.size(2);
  int64_t Win = x_c.size(3);

  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal in_channels");
  int64_t Cout_per_group = w_c.size(1);
  int64_t kH = w_c.size(2);
  int64_t kW = w_c.size(3);
  int64_t Cout = Cout_per_group * groups;
  int64_t Cin_per_group = Cin / groups;

  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dilation_h > 0 && dilation_w > 0, "dilation must be > 0");
  TORCH_CHECK(padding_h >= 0 && padding_w >= 0, "padding must be >= 0");
  TORCH_CHECK(groups > 0, "groups must be > 0");

  int64_t Hout = (H - 1) * stride_h - 2 * padding_h + dilation_h * (kH - 1) + 1;
  int64_t Wout = (Win - 1) * stride_w - 2 * padding_w + dilation_w * (kW - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads = 128;
  constexpr int PVec = 8;
  const int CoutPerBlock = (int)std::min<int64_t>(Cout_per_group, 16);

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout_per_group + CoutPerBlock - 1) / CoutPerBlock),
      (unsigned)(N * groups)
  );

  size_t smem_bytes = (size_t)CoutPerBlock * Cin_per_group * kH * kW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  convtranspose2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Hout, (int)Wout,
      (int)kH, (int)kW,
      stride_h, stride_w,
      padding_h, padding_w,
      dilation_h, dilation_w,
      groups,
      (int)Cin_per_group, (int)Cout_per_group,
      CoutPerBlock
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convtranspose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

_ext = load_inline(
    name="cute_convtranspose2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["convtranspose2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Grouped, dilated, padded, strided 2D transposed convolution implemented with
    a single custom cooperative-tiled CUDA/CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        kH, kW = kernel_size
        # PyTorch ConvTranspose2d weight layout: (in_channels, out_channels/groups, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = _ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels // self.groups
            for k in self.kernel_size:
                fan_in *= k
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.convtranspose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
            int(self.groups),
        )

