  // CoutPerBlock is placed as the fastest-varying dimension so that the inner
  // accumulation loop can read 4 output-channel weights at once via a single
  // 16B-aligned float4 shared-memory load instead of 4 separate scalar loads.
  extern __shared__ int4 smem_raw4[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw4);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Cin_per_group, kH, kW, CoutPerBlock),
      make_stride((int64_t)kH * kW * CoutPerBlock, (int64_t)kW * CoutPerBlock, (int64_t)CoutPerBlock, Int<1>{})
  );

  const int weight_tile_elems = CoutPerBlock * Cin_per_group * kH * kW;
  for (int idx = tid; idx < weight_tile_elems; idx += Threads) {
    int rem = idx;
    int kw = rem % kW; rem /= kW;
    int kh = rem % kH; rem /= kH;
    int cin = rem % Cin_per_group; rem /= Cin_per_group;
    int cc = rem;

    int oc_local = oc_local_base + cc;
    int ic_global = cin_start + cin;

    T wval = T(0);
    if (oc_local < Cout_per_group && ic_global < Cin) {
      wval = mW(ic_global, oc_local, kh, kw);
    }
    sW(cin, kh, kw, cc) = wval;
  }
  __syncthreads();

  // Precompute output position indices for this thread
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

