        if (!is_last_cin) {
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xval_cur[i] = xval_next[i];
          }
        }
      }
      if (has_next_kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
